package registrycleanupschedule

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

// corpusCase is one creation body judged by the PLATFORM's own code.
//
// `testdata/api_corpus.json` is generated by running every case through
// `CleanupScheduleCreate` of cetic-cloud-platform (origin/main, release
// v4.30.0, #1986: `app/schemas/registry_retention.py` +
// `app/services/registry_cleanup.py`, pydantic 2.10): `api_accepts` is the
// API's verdict, not ours. Hand-picked edge cases (raw vs stripped lengths,
// Python whitespace U+001C..U+001F, `**`, universal patterns, cron grammar)
// plus a seeded random sweep of crons and patterns. Regenerate it with
// `testdata/gen_corpus.py` (instructions in its header) when the platform's
// validation changes.
type corpusCase struct {
	Name         string   `json:"name"`
	RepoPatterns []string `json:"repo_patterns"`
	TagPatterns  []string `json:"tag_patterns"`
	Critere      string   `json:"critere"`
	Valeur       *int64   `json:"valeur"`
	Cron         *string  `json:"cron"`
	APIAccepts   bool     `json:"api_accepts"`
}

func strList(v []string) types.List {
	el := make([]attr.Value, 0, len(v))
	for _, s := range v {
		el = append(el, types.StringValue(s))
	}
	return types.ListValueMust(types.StringType, el)
}

func (c corpusCase) model() cleanupScheduleModel {
	m := cleanupScheduleModel{
		RegistryID:   types.StringValue("reg-1"),
		Name:         types.StringValue(c.Name),
		RepoPatterns: strList(c.RepoPatterns),
		TagPatterns:  strList(c.TagPatterns),
		Criterion:    types.StringValue(c.Critere),
		Value:        types.Int64Null(),
		Cron:         types.StringNull(),
		Enabled:      types.BoolValue(true),
	}
	if c.Valeur != nil {
		m.Value = types.Int64Value(*c.Valeur)
	}
	if c.Cron != nil {
		m.Cron = types.StringValue(*c.Cron)
	}
	return m
}

func (c corpusCase) hasNonASCII() bool {
	all := append([]string{c.Name}, c.RepoPatterns...)
	all = append(all, c.TagPatterns...)
	if c.Cron != nil {
		all = append(all, *c.Cron)
	}
	for _, s := range all {
		if !isASCII(s) {
			return true
		}
	}
	return false
}

// The plan-time validation must never refuse what the API accepts, and must
// refuse everything it refuses — except where a value holds non-ASCII text,
// left to the API on purpose (Python/Go whitespace and length rules differ).
func TestValidation_MatchesThePlatformCorpus(t *testing.T) {
	raw, err := os.ReadFile("testdata/api_corpus.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []corpusCase
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	if len(cases) < 500 {
		t.Fatalf("corpus trop petit (%d cas) : fichier tronqué ?", len(cases))
	}
	accepted, deferred := 0, 0
	for i, c := range cases {
		diags := validateModel(c.model())
		goAccepts := !diags.HasError()
		if c.APIAccepts {
			accepted++
		}
		switch {
		case goAccepts == c.APIAccepts:
		case goAccepts && c.hasNonASCII():
			deferred++ // left to the API: never stricter, only silent
		case goAccepts:
			t.Errorf("cas %d : l'API refuse, le provider laisse passer : %+v", i, c)
		default:
			t.Errorf("cas %d : l'API accepte, le provider refuse (%v) : %+v", i, diags, c)
		}
	}
	if accepted < 100 || accepted == len(cases) {
		t.Fatalf("corpus déséquilibré : %d acceptés sur %d", accepted, len(cases))
	}
	t.Logf("%d cas, %d acceptés par l'API, %d laissés à l'API (non ASCII)", len(cases), accepted, deferred)
}

// Unknown values (module variables, other resources' attributes) are never
// judged: `terraform validate` of a consuming module must pass.
func TestValidation_UnknownValuesAreNotJudged(t *testing.T) {
	m := cleanupScheduleModel{
		RegistryID:   types.StringUnknown(),
		Name:         types.StringUnknown(),
		RepoPatterns: types.ListUnknown(types.StringType),
		TagPatterns:  types.ListValueMust(types.StringType, []attr.Value{types.StringUnknown()}),
		Criterion:    types.StringUnknown(),
		Value:        types.Int64Unknown(),
		Cron:         types.StringUnknown(),
		Enabled:      types.BoolUnknown(),
	}
	if d := validateModel(m); d.HasError() {
		t.Fatalf("valeurs inconnues jugées : %v", d)
	}
	// Criterion known, value unknown: no value check.
	m.Criterion = types.StringValue(critereOlderThan)
	if d := validateModel(m); d.HasError() {
		t.Fatalf("value inconnue jugée : %v", d)
	}
	// Patterns unknown: the "whole registry" guard cannot fire.
	m.Criterion = types.StringValue(critereAll)
	m.Value = types.Int64Null()
	m.TagPatterns = strList([]string{"*"})
	if d := validateModel(m); d.HasError() {
		t.Fatalf("garde-fou motifs universels sur motifs inconnus : %v", d)
	}
	// A known universal repo pattern next to an unknown one still decides.
	m.RepoPatterns = types.ListValueMust(types.StringType, []attr.Value{types.StringUnknown(), types.StringValue("*/*")})
	d := validateModel(m)
	if !d.HasError() || !strings.Contains(d[0].Detail(), "empty the whole registry") {
		t.Fatalf("« all » sur */* × * doit être refusé au plan, reçu %v", d)
	}
}

func TestCheckCriterion_Messages(t *testing.T) {
	v := func(n int64) *int64 { return &n }
	for _, tc := range []struct {
		critere string
		value   *int64
		every   tri
		want    string
	}{
		{critereAll, v(1), triFalse, "takes no value"},
		{critereAll, nil, triTrue, "empty the whole registry"},
		{critereAll, nil, triUnknown, ""},
		{critereOlderThan, nil, triFalse, "1 to 3650"},
		{critereOlderThan, v(6), triTrue, "at least 7 days"},
		{critereOlderThan, v(6), triFalse, ""},
		{critereOlderThan, v(6), triUnknown, ""},
		{critereKeepLastN, v(1001), triFalse, "1 to 1000"},
		{critereKeepLastN, v(1), triTrue, ""},
	} {
		got := checkCriterion(tc.critere, tc.value, false, tc.every)
		if (tc.want == "") != (got == "") || !strings.Contains(got, tc.want) {
			t.Errorf("%s %v %v : %q, attendu %q", tc.critere, tc.value, tc.every, got, tc.want)
		}
	}
}

func TestNormalizeCron(t *testing.T) {
	if normalizeCron("  \t") != nil {
		t.Error("cron blanc : nil attendu (manuel)")
	}
	if got := normalizeCron(" 0  3\t* * *\x1c"); got == nil || *got != "0 3 * * *" {
		t.Errorf("cron réduit : %v", got)
	}
}
